def get_text(key: str, lang: str = "uz", **kwargs) -> str:
    lang_dict = MESSAGES.get(lang, MESSAGES["uz"])
    text = lang_dict.get(key, MESSAGES["uz"].get(key, key))
    if kwargs:
        try:
            return text.format(**kwargs)
        except Exception:
            return text
    return text
